// Db2ParserInit initializes any static state used to implement Db2Parser. By default the
// static state used to implement the parser is lazily initialized during the first call to
// NewDb2Parser(). You can call this function if you wish to initialize the static state ahead
// of time.
func Db2ParserInit() {
	staticData := &Db2ParserParserStaticData
	staticData.once.Do(db2parserParserInit)
}

// NewDb2Parser produces a new parser instance for the optional input antlr.TokenStream.
func NewDb2Parser(input antlr.TokenStream) *Db2Parser {
	Db2ParserInit()
	this := new(Db2Parser)
	this.BaseParser = antlr.NewBaseParser(input)
	staticData := &Db2ParserParserStaticData
	this.Interpreter = antlr.NewParserATNSimulator(this, staticData.atn, staticData.decisionToDFA, staticData.PredictionContextCache)
	this.RuleNames = staticData.RuleNames
	this.LiteralNames = staticData.LiteralNames
	this.SymbolicNames = staticData.SymbolicNames
	this.GrammarFileName = "Db2Parser.g4"

	return this
}

